python3 - <<'PY'
p='tests/codegen/io/streams.rs'
s=open(p).read()
# stream_get_contents() is string|false, so the helper cannot declare a bare `string` return
s=s.replace('''function qp(string $data): string {
    $m = fopen("php://memory", "r+");
    stream_filter_append($m, "convert.quoted-printable-encode", STREAM_FILTER_WRITE);
    fwrite($m, $data);
    rewind($m);
    $out = stream_get_contents($m);
    fclose($m);
    return $out;
}''','''function qp(string $data): string {
    $m = fopen("php://memory", "r+");
    stream_filter_append($m, "convert.quoted-printable-encode", STREAM_FILTER_WRITE);
    fwrite($m, $data);
    rewind($m);
    $out = (string) stream_get_contents($m);
    fclose($m);
    return $out;
}''')
s=s.replace('''function w(string $data, $length): string {
    $m = fopen("php://memory", "r+");
    $n = $length === "omit" ? fwrite($m, $data) : fwrite($m, $data, $length);
    rewind($m);
    $got = stream_get_contents($m);
    fclose($m);
    return $n . ":" . $got;
}''','''function w(string $data, $length): string {
    $m = fopen("php://memory", "r+");
    $n = $length === "omit" ? fwrite($m, $data) : fwrite($m, $data, $length);
    rewind($m);
    $got = (string) stream_get_contents($m);
    fclose($m);
    return $n . ":" . $got;
}''')
open(p,'w').write(s)
print("casts added")
